// \u05D0\u05D9\u05DF total, \u05D0\u05D9\u05DF "\u05E2\u05DE\u05D5\u05D3 N \u05DE\u05EA\u05D5\u05DA M" \u2014 \u05E8\u05E7 "\u05D9\u05E9 \u05E2\u05D5\u05D3" (hasMore)`}},{id:"28.6",title:"infinite scroll \u2014 IntersectionObserver \u05D5-scan",blocks:[{kind:"p",text:"infinite scroll \u05DE\u05E6\u05E8\u05E3 \u05D7\u05DC\u05D5\u05E0\u05D5\u05EA: \u05DB\u05DC \u05E4\u05E2\u05DD \u05E9\u05D4\u05DE\u05E9\u05EA\u05DE\u05E9 \u05DE\u05D2\u05D9\u05E2 \u05DC\u05EA\u05D7\u05EA\u05D9\u05EA \u05D4\u05E8\u05E9\u05D9\u05DE\u05D4, \u05E0\u05D8\u05E2\u05E0\u05D9\u05DD \u05E2\u05D5\u05D3 \u05E4\u05E8\u05D9\u05D8\u05D9\u05DD \u05D5\u05DE\u05EA\u05D5\u05D5\u05E1\u05E4\u05D9\u05DD \u05DC\u05E1\u05D5\u05E3 (`scan`-style). \u05D4\u05D6\u05E7\u05D9\u05E3 \u05D4\u05D5\u05D0 \u05D0\u05DC\u05DE\u05E0\u05D8 \u05E8\u05D9\u05E7 \u05D1\u05EA\u05D7\u05EA\u05D9\u05EA \u05E8\u05E9\u05D9\u05DE\u05EA \u05D4\u05D2\u05DC\u05D9\u05DC\u05D4; `IntersectionObserver` \u05DE\u05D2\u05DC\u05D4 \u05DB\u05E9\u05D4\u05D5\u05D0 \u05E0\u05DB\u05E0\u05E1 \u05DC-viewport \u05D5\u05DE\u05E4\u05E2\u05D9\u05DC \u05D8\u05E2\u05D9\u05E0\u05D4."},{kind:"p",text:'\u05D1\u05D3\u05DE\u05D5: \u05D8\u05D0\u05D1 "infinite" \u05DE\u05E6\u05D9\u05D2 137 \u05E9\u05D5\u05E8\u05D5\u05EA. \u05DB\u05E9\u05D2\u05D5\u05DC\u05DC\u05D9\u05DD \u05DC\u05E1\u05D5\u05E3, \u05D4-`IntersectionObserver` \u05E2\u05DC \u05D4\u05D6\u05E7\u05D9\u05E3 \u05DE\u05D6\u05D4\u05D4 \u05D4\u05E6\u05D8\u05DC\u05D1\u05D5\u05EA \u05D5\u05DE\u05E6\u05E8\u05E3 \u05D7\u05DC\u05D5\u05DF \u05E0\u05D5\u05E1\u05E3 \u2014 \u05E2\u05D3 \u05E9\u05E0\u05D2\u05DE\u05E8\u05D5\u05EA \u05D4\u05E9\u05D5\u05E8\u05D5\u05EA. \u05DB\u05DC \u05E6\u05D1\u05D9\u05E8\u05D4 \u05D4\u05D9\u05D0 `scan((acc, page) => [...acc, ...page], [])` \u05DE\u05E2\u05DC \u05D4-Observable \u05E9\u05DC \u05D4\u05D1\u05E7\u05E9\u05D5\u05EA.'},{kind:"callout",tone:"alt",title:'infinite scroll \u05DE\u05D5\u05DC "\u05D8\u05E2\u05DF \u05E2\u05D5\u05D3" \u05DB\u05E4\u05EA\u05D5\u05E8',body:'\u05DB\u05E4\u05EA\u05D5\u05E8 "\u05D8\u05E2\u05DF \u05E2\u05D5\u05D3" \u05D4\u05D5\u05D0 \u05D2\u05E8\u05E1\u05D4 \u05DE\u05E4\u05D5\u05E8\u05E9\u05EA: \u05D4\u05DE\u05E9\u05EA\u05DE\u05E9 \u05E9\u05D5\u05DC\u05D8 \u05DE\u05EA\u05D9 \u05E0\u05D8\u05E2\u05DF \u05D4\u05E1\u05D2\u05DE\u05E0\u05D8 \u05D4\u05D1\u05D0. \u05DE\u05EA\u05D0\u05D9\u05DD \u05DB\u05E9\u05E8\u05D5\u05E6\u05D9\u05DD \u05E9\u05D4\u05DE\u05E9\u05EA\u05DE\u05E9 \u05D9\u05D5\u05DB\u05DC \u05DC\u05D7\u05D6\u05D5\u05E8 \u05DC\u05D0\u05D7\u05E8\u05D5\u05E0\u05D4 \u05E9\u05E8\u05D0\u05D4 (\u05DB\u05D9 \u05D4\u05DE\u05D9\u05E7\u05D5\u05DD \u05E9\u05DE\u05D5\u05E8 \u05D1-scroll). infinite scroll (\u05D0\u05D5\u05D8\u05D5\u05DE\u05D8\u05D9) \u05D7\u05DC\u05E7 \u05D9\u05D5\u05EA\u05E8, \u05D0\u05D1\u05DC \u05E7\u05E9\u05D4 \u05DC\u05E9\u05EA\u05E3/\u05DC\u05E1\u05DE\u05DF \u05DE\u05D9\u05E7\u05D5\u05DD.'}],panel:{kind:"code-inline",lang:"typescript",code:`// infinite scroll \u2014 IntersectionObserver \u05E2\u05DC \u05D6\u05E7\u05D9\u05E3 + scan \u05DC\u05E6\u05D1\u05D9\u05E8\u05D4
ngAfterViewInit() {
  const sentinel = this.sentinelRef.nativeElement;
  const obs = new IntersectionObserver(
    entries => {
      if (entries[0].isIntersecting && !this.loading() && this.hasMore()) {
        this.loadNextPage();
      }
    },
    { threshold: 0.1 }
  );
  obs.observe(sentinel);
  // \u05E0\u05D9\u05E7\u05D5\u05D9 \u05D1-DestroyRef
  this.destroyRef.onDestroy(() => obs.disconnect());
}

